spec.entryPoints:
{
  "$schema": "https://cloud.uipath.com/draft/2024-12/entry-point",
  "$id": "entry-points.json",
  "entryPoints": [
    {
      "filePath": "/content/agent.json",
      "uniqueId": "ba3a387f-1d9b-47ca-bca4-b86f4638163e",
      "type": "agent",
      "input": {
        "type": "object",
        "required": [
          "caseInstanceId",
          "folderKey"
        ],
        "properties": {
          "caseInstanceId": {
            "type": "string",
            "description": "The Case Management case instance ID for this property claim. Passed as the caseInstanceId parameter to the Get Case Plan and Get Case Rules tools."
          },
          "folderKey": {
            "type": "string",
            "description": "The Orchestrator folder key where the case plan and rules workflows are deployed. Passed directly to both tools. This is a deployment-time constant for the solution folder."
          },
          "caseCurrentExecutionState": {
            "type": "object",
            "description": "Engine snapshot for this invocation. Contains: event (type + parameters, isExternal), state.tasksRunning (with name + identifier), state.tasksCompleted, state.stagesEntered, state.stagesExited, state.stagesCompleted, state.vars (the case variables, e.g. claimReference, injuryTypeCode, liabilityBasisCode, fraudScore, liabilityOutcome, hiddenDamageFound, estimatedCost).",
            "properties": {}
          },
          "caseRulesDecisions": {
            "type": "object",
            "description": "The decision produced by the deterministic rules layer for this event. May be empty when no rule matched.",
            "properties": {}
          },
          "eventId": {
            "type": "string",
            "description": "Optional. Set only when the invocation was triggered by an external event whose richer payload is stored separately and must be fetched via an attached tool."
          }
        }
      },
      "output": {
        "type": "object",
        "required": [
          "caseManagerDecisions"
        ],
        "properties": {
          "caseManagerDecisions": {
            "type": "object",
            "description": "All orchestration actions the agent has decided to take for this invocation.",
            "properties": {
              "tasksToRun": {
                "type": "array",
                "description": "Tasks the agent wants to start. Each entry must use the canonical taskName from the Case Plan.",
                "items": {
                  "type": "object",
                  "required": [
                    "taskName",
                    "triggeringDecision"
                  ],
                  "properties": {
                    "taskName": {
                      "type": "string",
                      "description": "Canonical task name copied verbatim from the Case Plan returned by Get Case Plan, including any trailing spaces."
                    },
                    "triggeringDecision": {
                      "type": "string",
                      "description": "Non-empty explanation of the signal or reasoning that drove this task being started."
                    }
                  }
                }
              },
              "tasksToCancel": {
                "type": "array",
                "description": "Tasks the agent wants to cancel. Each entry must use the running task identifier from the execution state, not the task name.",
                "items": {
                  "type": "object",
                  "required": [
                    "identifier",
                    "triggeringDecision"
                  ],
                  "properties": {
                    "identifier": {
                      "type": "string",
                      "description": "Running task identifier from caseCurrentExecutionState.state.tasksRunning — not the task name."
                    },
                    "triggeringDecision": {
                      "type": "string",
                      "description": "Non-empty explanation of why this running task is being cancelled."
                    }
                  }
                }
              },
              "stagesEntered": {
                "type": "array",
                "description": "Stages the agent wants to enter. Each entry must use the canonical stageName from the Case Plan.",
                "items": {
                  "type": "object",
                  "required": [
                    "stageName",
                    "triggeringDecision"
                  ],
                  "properties": {
                    "stageName": {
                      "type": "string",
                      "description": "Canonical stage name copied verbatim from the Case Plan returned by Get Case Plan, including any trailing spaces."
                    },
                    "triggeringDecision": {
                      "type": "string",
                      "description": "Non-empty explanation of the signal that drove this stage transition."
                    }
                  }
                }
              },
              "stagesExited": {
                "type": "array",
                "description": "Stages the agent wants to exit without completing — an early exit or rework path — for example when an event invalidates the stage's premise.",
                "items": {
                  "type": "object",
                  "required": [
                    "stageName",
                    "triggeringDecision"
                  ],
                  "properties": {
                    "stageName": {
                      "type": "string",
                      "description": "Canonical stage name copied verbatim from the Case Plan returned by Get Case Plan, including any trailing spaces."
                    },
                    "triggeringDecision": {
                      "type": "string",
                      "description": "Non-empty explanation of why this stage is being exited without completing."
                    }
                  }
                }
              },
              "stagesCompleted": {
                "type": "array",
                "description": "Stages the agent judges complete because all required tasks have finished.",
                "items": {
                  "type": "object",
                  "required": [
                    "stageName",
                    "triggeringDecision"
                  ],
                  "properties": {
                    "stageName": {
                      "type": "string",
                      "description": "Canonical stage name copied verbatim from the Case Plan returned by Get Case Plan, including any trailing spaces."
                    },
                    "triggeringDecision": {
                      "type": "string",
                      "description": "Non-empty explanation of why this stage is judged complete."
                    }
                  }
                }
              },
              "traces": {
                "type": "array",
                "description": "Escalation messages and reasoning traces. Populated when the agent cannot fully resolve a decision, encounters contradictory signals, or must escalate a decision reserved for a person rather than decide it.",
                "items": {
                  "type": "object",
                  "required": [
                    "message"
                  ],
                  "properties": {
                    "message": {
                      "type": "string",
                      "description": "Escalation message or reasoning trace explaining the unresolved signal or the decision being handed to a person."
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  ]
}
